/* 启动版本包含 MMIO 完成确认与关机排空协议，拒绝旧版混用。 */
#define ROUTER_PROTOCOL_VERSION 6
#define ROUTER_HELLO 0x53534948
#define ROUTER_HELLO_ACK 0x53534941
#define ROUTER_STARTUP_TIMEOUT_MS 15000
#define ROUTER_DRAIN_ACK 0x44524149
#define ROUTER_DRAIN_TIMEOUT_MS 15000
#define MMIO_WRITE_COMPLETE 0x4d4d494f
#define ROUTER_BUFFER_SIZE 1024
// #define ROUTER_CONNECTION_UNIX_SOCKET
#define ROUTER_CONNECTION_TCP
//#define ROUTER_CONNECTION_RDMA

/* Unix socket */
#define ROUTER_SOCKET_PREFIX "/home/binss/work/qemu-io-router-socket"

/* TCP */
#define ROUTER_HOST_LOCALHOST "127.0.0.1"
#define ROUTER_DEFAULT_PORT 40000
#define ROUTER_MAX_INDEX 63
#define CPU_INDEX_ANY -1

/* RDMA */
//#define ROUTER_RDMA_DEBUG
static char **router_hosts = NULL;
static uint32_t router_hosts_num = 0;

static QEMUFile **req_files = NULL;
static QEMUFile **rsp_files = NULL;
static QEMUFile **listen_req_files = NULL;
static QEMUFile **listen_rsp_files = NULL;

QemuMutex ipi_mutex;
QemuMutex io_forwarding_mutex;

/* 主线程和各入站处理器共同维护单次关闭屏障，不用 EOF 代替确认。 */
static QemuMutex drain_mutex;
static QemuCond drain_cond;
typedef struct RouterBarrier {
    bool started;
    bool finished;
    uint64_t seen;
    uint64_t received;
    uint64_t nonce;
    const char *name;
} RouterBarrier;

static RouterBarrier quiesce = { .name = "QUIESCE" };
static RouterBarrier drain = { .name = "DRAIN" };
static uint64_t close_generation;

static unsigned int router_index(void)
{
    MachineState *ms = MACHINE(qdev_get_machine());
    return ms->local_cpu_start_index / ms->local_cpus;
}

/* 连接版本必须在任何设备报文与客体执行之前确定，不能借可变长时钟帧协商。 */
static QemuMutex startup_mutex;
static QemuCond startup_cond;
static bool startup_complete;
static uint64_t startup_received;

static void router_startup_fail(const char *reason)
{
    error_report("SSI router startup protocol error: %s", reason);
    /* 初始化线程可能持有 BQL，失败停止不能等待正常退出通知再次取锁。 */
    _exit(EXIT_FAILURE);
}

static void *router_startup_watchdog(void *opaque)
{
    int64_t deadline = qemu_clock_get_ms(QEMU_CLOCK_REALTIME) + ROUTER_STARTUP_TIMEOUT_MS;

    qemu_mutex_lock(&startup_mutex);
    while (!startup_complete) {
        int64_t left = deadline - qemu_clock_get_ms(QEMU_CLOCK_REALTIME);
        if (left <= 0) {
            router_startup_fail("deadline expired before compatible peers were ready");
        }
        qemu_cond_timedwait(&startup_cond, &startup_mutex, left);
    }
    qemu_mutex_unlock(&startup_mutex);
    return NULL;
}

static void router_write_hello(QEMUFile *file, uint32_t magic, unsigned int target)
{
    MachineState *ms = MACHINE(qdev_get_machine());

    qemu_put_be32(file, magic);
    qemu_put_be32(file, ROUTER_PROTOCOL_VERSION);
    qemu_put_be32(file, router_index());
    qemu_put_be32(file, target);
    qemu_put_be32(file, ms->qemu_nums);
    qemu_put_be32(file, ms->smp.cpus);
    qemu_put_be32(file, ms->local_cpus);
    qemu_fflush(file);
    if (qemu_file_get_error(file)) {
        router_startup_fail("hello send failed");
    }
}

static unsigned int router_read_hello(QEMUFile *file, uint32_t expected_magic)
{
    MachineState *ms = MACHINE(qdev_get_machine());
    uint32_t magic = qemu_get_be32(file);

    /* 先校验固定前缀，不读取旧版可能永远不会发送的剩余字段。 */
    if (qemu_file_get_error(file) || magic != expected_magic) {
        router_startup_fail("missing or invalid hello magic");
    }
    uint32_t version = qemu_get_be32(file);
    if (qemu_file_get_error(file) || version != ROUTER_PROTOCOL_VERSION) {
        router_startup_fail("incompatible protocol version");
    }
    uint32_t sender = qemu_get_be32(file);
    uint32_t target = qemu_get_be32(file);
    uint32_t nodes = qemu_get_be32(file);
    uint32_t cpus = qemu_get_be32(file);
    uint32_t local_cpus = qemu_get_be32(file);
    if (qemu_file_get_error(file) || sender >= ms->qemu_nums ||
        sender == router_index() || target != router_index() ||
        nodes != ms->qemu_nums || cpus != ms->smp.cpus ||
        local_cpus != ms->local_cpus) {
        router_startup_fail("incomplete hello or mismatched node topology");
    }
    return sender;
}

static void router_accept_hello(QEMUFile *request, QEMUFile *response)
{
    unsigned int peer = router_read_hello(request, ROUTER_HELLO);

    qemu_mutex_lock(&startup_mutex);
    if (startup_received & (UINT64_C(1) << peer)) {
        router_startup_fail("duplicate peer connection");
    }
    startup_received |= UINT64_C(1) << peer;
    qemu_mutex_unlock(&startup_mutex);
    router_write_hello(response, ROUTER_HELLO_ACK, peer);
    fprintf(stderr, "SSI_ROUTER_HELLO_RECEIVED node=%u peer=%u version=%u\n",
            router_index(), peer, ROUTER_PROTOCOL_VERSION);
    qemu_mutex_lock(&startup_mutex);
    qemu_cond_broadcast(&startup_cond);
    /* 单个连接通过不等于本节点全部出入站连接都已通过。 */
    while (!startup_complete) {
        qemu_cond_wait(&startup_cond, &startup_mutex);
    }
    qemu_mutex_unlock(&startup_mutex);
}

static void router_forward_lock(void)
{
    qemu_mutex_lock(&io_forwarding_mutex);
    if (qatomic_read(&drain.started)) {
        error_report("SSI router generated traffic after local drain");
        exit(EXIT_FAILURE);
    }
}

static void *router_drain_watchdog(void *opaque)
{
    RouterBarrier *barrier = opaque;
    int64_t deadline = qemu_clock_get_ms(QEMU_CLOCK_REALTIME) + ROUTER_DRAIN_TIMEOUT_MS;

    qemu_mutex_lock(&drain_mutex);
    while (!barrier->finished) {
        int64_t left = deadline - qemu_clock_get_ms(QEMU_CLOCK_REALTIME);
        if (left <= 0) {
            error_report("SSI router drain deadline expired");
            exit(EXIT_FAILURE);
        }
        qemu_cond_timedwait(&drain_cond, &drain_mutex, left);
    }
    qemu_mutex_unlock(&drain_mutex);
    return NULL;
}


int parse_cluster_iplist(const char *cluster_iplist)
{
    int ret = 0, ip_num = 0, i;

    if (cluster_iplist == NULL) {
        ret = -EINVAL;
        goto out;
    }

    for (i = 0; cluster_iplist[i] != '\0'; i++) {
        if (isspace(cluster_iplist[i]))
            ip_num++;
        else if (!(isdigit(cluster_iplist[i]) || cluster_iplist[i] == '.')) {
            ret = -EINVAL;
            goto out;
        }
    }
    router_hosts_num = ++ip_num;

    router_hosts = (char **)g_malloc0(sizeof(char *) * ip_num);

    char *temp_iplist = (char *)g_malloc(strlen(cluster_iplist) + 1);
    strcpy(temp_iplist, cluster_iplist);
    char *parse_ip = strtok(temp_iplist, " ");
    i = 0;
    while (parse_ip != NULL) {
        char *ip = (char *)g_malloc(20);
        strcpy(ip, parse_ip);
        router_hosts[i++] = ip;
        parse_ip = strtok(NULL, " ");
    }
    g_free(temp_iplist);

out:
    return ret;
}

char **get_cluster_iplist(uint32_t *len)
{
    *len = router_hosts_num;
    return router_hosts;
}



enum forward_type {
    PIO = 1,
    MMIO,
    LAPIC,
    SPECIAL_INT,
    SIPI,
    X2APIC,
    APIC_BASE,
    INIT_LEVEL_DEASSERT,
    FIXED_INT,
    IOAPIC_INI,
    IOAPIC,
    KVMCLOCK,
    INI_ROUTER,
    /* IO_ROUTER_EXIT */
    SHUTDOWN,
    RESET,
    EXIT,
    DRAIN,
    CLOCK_BARRIER,
    QUIESCE,
};

enum rdma_role {
    RDMA_LISTEN,
    RDMA_LISTEN_REVERSE,
    RDMA_CONNECT,
    RDMA_CONNECT_REVERSE,
};

static void kvm_handle_remote_io(uint16_t port, MemTxAttrs attrs, void *data, int direction,
                          int size, uint32_t count)
{
    int i;
    uint8_t *ptr = data;

    for (i = 0; i < count; i++) {
        address_space_rw(&address_space_io, port, attrs,
                         ptr, size,
                         direction == KVM_EXIT_IO_OUT);
        ptr += size;
    }
}

static void *io_router_loop(void *arg)
{
    printf("enter router_loop\n");
    fflush(stdout);
    uint16_t type;
    bool drained = false;
    int cpu_index;
    Error *err = NULL;

    /* PIO */
    uint16_t port;
    MemTxAttrs attrs;
    int direction;
    int size;
    uint32_t count;

    /* MMIO */
    hwaddr addr;
    bool is_write;
    int len;

    /* Interrupts */
    uint32_t val; /* LAPIC */
    uint32_t val2;
    uint32_t dest_id;
    int mask; /* SPECIAL_INT */
    int vector_num; /* SIPI & FIXED_INT */
    int trigger_mode; /* FIXED_INT */
    int isrv; /* IOAPIC */

    __u64 x2data;

    int host;
    uint32_t base_index;
    __u64 base_data;

    void *data;
    struct io_router_loop_arg *argp = (struct io_router_loop_arg *)arg;
    QEMUFile *req_file = argp->req_file;
    QEMUFile *rsp_file = argp->rsp_file;

    router_accept_hello(req_file, rsp_file);
    while(1) {
        type = qemu_get_be16(req_file);
        if (!type) {
            if (!drained || qemu_file_get_error(req_file) != -EIO) {
                error_report("SSI router EOF before acknowledged drain");
                exit(EXIT_FAILURE);
            }
            break;
        }
        if (drained) {
            error_report("SSI router received traffic after drain marker");
            exit(EXIT_FAILURE);
        }

        cpu_index = qemu_get_sbe32(req_file);
        if (cpu_index != CPU_INDEX_ANY) {
            current_cpu = qemu_get_cpu(cpu_index);
        }
        switch(type)
        {
            case PIO:
                /* AP forward to BSP */

                /*
                 * indicate which cpu we are currently operating on, especially
                 * for apic_mem_readl / apic_mem_writel => cpu_get_current_apic
                 */
                port = qemu_get_be16(req_file);
                qemu_get_buffer(req_file, (uint8_t *)&attrs, sizeof(attrs));
                direction = qemu_get_sbe32(req_file);
                size = qemu_get_sbe32(req_file);
                count = qemu_get_be32(req_file);
                data = malloc(count * size);
                qemu_get_buffer(req_file, data, count * size);

                kvm_handle_remote_io(port, attrs, data, direction, size, count);

                if (direction == KVM_EXIT_IO_IN) {
                    qemu_put_buffer(rsp_file, data, count * size);
                    qemu_fflush(rsp_file);
                }
                free(data);
                break;

            case MMIO:
                /* AP forward to BSP */
                addr = qemu_get_be64(req_file);
                qemu_get_buffer(req_file, (uint8_t *)&attrs, sizeof(attrs));
                len = qemu_get_sbe32(req_file);
                is_write = qemu_get_sbe32(req_file) ? true : false;
                if (len < 1 || len > 8 || qemu_file_get_error(req_file)) {
                    error_report("SSI MMIO invalid or incomplete request header");
                    exit(1);
                }
                data = malloc(len);
                if (qemu_get_buffer(req_file, data, len) != len ||
                    qemu_file_get_error(req_file)) {
                    error_report("SSI MMIO incomplete request payload");
                    exit(1);
                }

                address_space_rw(&address_space_memory, addr, attrs, data, len, is_write);

                if (!is_write) {
                    qemu_put_buffer(rsp_file, data, len);
                } else {
                    /* 完成的是设备模拟操作，不是磁盘持久化或设备内部异步工作。 */
                    qemu_put_be32(rsp_file, MMIO_WRITE_COMPLETE);
                }
                qemu_fflush(rsp_file);
                if (qemu_file_get_error(rsp_file)) {
                    error_report("SSI MMIO response failed: %s",
                                 strerror(-qemu_file_get_error(rsp_file)));
                    exit(1);
                }

                free(data);
                break;

            case LAPIC:
                /* Any CPU broadcast to others */
                addr = qemu_get_be64(req_file);
                val = qemu_get_be32(req_file);
                apic_lapic_write(current_cpu, addr, val);
                break;
            case SPECIAL_INT:
                /* Any CPU send to target CPUs of a multicast/broadcast of SMI/NMI/INIT */
                mask = qemu_get_sbe32(req_file);
                cpu_interrupt(current_cpu, mask);
                break;
            case X2APIC:
                x2data = qemu_get_be64(req_file);
                int ret = kvm_x2apic_handle(cpu_index, x2data);
                if (ret < 0) {
                    error_report("KVM DSM x2APIC injection for vCPU %d "
                                 "failed: %s",
                                 cpu_index, strerror(-ret));
                }
                break;
            case SIPI:
                /* Any CPU send to target CPUs of a multicast/broadcast of SIPI */
                val = qemu_get_sbe32(req_file);
                val2 = qemu_get_sbe32(req_file);
                dest_id = qemu_get_be32(req_file);
                ret = kvm_dipi_forwarding(cpu_index, val, val2, dest_id);
                if (ret < 0) {
                    error_report("KVM DSM IPI injection for vCPU %d failed: %s",
                                 cpu_index, strerror(-ret));
                }
                // apic_startup(current_cpu, vector_num);
                break;
            case APIC_BASE:
                host = qemu_get_sbe32(req_file);
                base_index = qemu_get_be32(req_file);
                base_data = qemu_get_be64(req_file);
                ret = kvm_apic_base_handle(cpu_index, host, base_index, base_data);
                if (ret < 0) {
                    error_report("KVM DSM APIC base update for vCPU %d "
                                 "failed: %s",
                                 cpu_index, strerror(-ret));
                }
                break;
            case INIT_LEVEL_DEASSERT:
                /* Any CPU send to target CPUs of a multicast/broadcast of INIT Level De-assert */
                apic_init_level_deassert(current_cpu);
                break;
            case FIXED_INT:
                /* Any CPU send to target CPU(s) a lowest-priority/multicast/broadcast interrupt */
                vector_num = qemu_get_sbe32(req_file);
                trigger_mode = qemu_get_sbe32(req_file);
                apic_set_irq_detour(current_cpu, vector_num, trigger_mode);
                break;
            case IOAPIC_INI:
                val = qemu_get_sbe32(req_file);
                val2 = qemu_get_sbe32(req_file);
                kvm_ioapic_irq_handle(val, val2);
                break;
            case IOAPIC:
                /* AP forward to BSP */
                isrv = qemu_get_sbe32(req_file);
                ioapic_eoi_broadcast(isrv);
                break;

            case INI_ROUTER:
                /* BSP forward to AP */
                uint32_t nr = qemu_get_be32(req_file);   
                uint32_t flags = qemu_get_be32(req_file); 

                struct kvm_irq_routing *routing = malloc(sizeof(*routing) + nr * sizeof(struct kvm_irq_routing_entry));
                routing->nr = nr;
                routing->flags = flags;

                for (int i = 0; i < nr; i++) {
                    struct kvm_irq_routing_entry *entry = &(routing->entries[i]);
                    entry->gsi = qemu_get_be32(req_file);
                    entry->type = qemu_get_be32(req_file);
                    entry->flags = qemu_get_be32(req_file);
                    entry->pad = qemu_get_be32(req_file);  

                    switch (entry->type) {
                    case KVM_IRQ_ROUTING_IRQCHIP: {
                        entry->u.irqchip.irqchip = qemu_get_be32(req_file);
                        entry->u.irqchip.pin = qemu_get_be32(req_file);
                        break;
                        }
                    case KVM_IRQ_ROUTING_MSI: {
                        entry->u.msi.address_lo = qemu_get_be32(req_file);
                        entry->u.msi.address_hi = qemu_get_be32(req_file);
                        entry->u.msi.data = qemu_get_be32(req_file);
                        entry->u.msi.pad = qemu_get_be32(req_file);
                        break;
                        }
                    default:
                        printf("unknown router type[%u]\n", entry->type);
                        exit(1);
                    }
                }
                kvm_ioapic_router_handle(routing);
                qemu_put_be32(rsp_file, 99);
                qemu_fflush(rsp_file);
                free(routing);
                break;

            case KVMCLOCK: {
                uint64_t epoch = qemu_get_be64(req_file);
                KVMClockSample sample = {};
                int sample_ret = qemu_file_get_error(req_file);

                if (!sample_ret) {
                    sample_ret = kvmclock_get_sample(epoch, &sample);
                }

                qemu_put_be32(rsp_file, ROUTER_PROTOCOL_VERSION);
                qemu_put_sbe32(rsp_file, sample_ret);
                qemu_put_be64(rsp_file, sample.epoch);
                qemu_put_be64(rsp_file, sample.clock);
                qemu_put_be64(rsp_file, sample.host_tsc);
                qemu_put_be64(rsp_file, sample.offset);
                qemu_put_be32(rsp_file, sample.flags);
                qemu_put_be32(rsp_file, sample.khz);
                qemu_fflush(rsp_file);
                break;
            }

            case CLOCK_BARRIER: {
                uint32_t version = qemu_get_be32(req_file);
                uint32_t sender = qemu_get_be32(req_file);
                uint32_t target = qemu_get_be32(req_file);
                uint64_t epoch = qemu_get_be64(req_file);
                uint32_t phase = qemu_get_be32(req_file);
                uint64_t clock_floor = qemu_get_be64(req_file);
                uint64_t tsc_floor = qemu_get_be64(req_file);

                if (qemu_file_get_error(req_file) ||
                    version != ROUTER_PROTOCOL_VERSION ||
                    sender != (router_index() ^ 1) || target != router_index() ||
                    cpu_index != CPU_INDEX_ANY ||
                    kvmclock_receive_barrier(epoch, phase, clock_floor, tsc_floor)) {
                    error_report("SSI invalid clock barrier");
                    exit(EXIT_FAILURE);
                }
                qemu_put_be32(rsp_file, ROUTER_PROTOCOL_VERSION);
                qemu_put_be32(rsp_file, target);
                qemu_put_be32(rsp_file, sender);
                qemu_put_be64(rsp_file, epoch);
                qemu_put_be32(rsp_file, phase);
                qemu_fflush(rsp_file);
                if (qemu_file_get_error(rsp_file)) {
                    error_report("SSI clock barrier acknowledgement failed");
                    exit(EXIT_FAILURE);
                }
                break;
            }

            case SHUTDOWN: {
                uint32_t version = qemu_get_be32(req_file);
                uint32_t cause = qemu_get_be32(req_file);
                int code = qemu_get_sbe32(req_file);

                if (qemu_file_get_error(req_file) || version != ROUTER_PROTOCOL_VERSION ||
                    cause <= SHUTDOWN_CAUSE_NONE || cause >= SHUTDOWN_CAUSE__MAX ||
                    code < 0 || code > 255 || router_index() == 0) {
                    error_report("SSI invalid shutdown notification");
                    exit(EXIT_FAILURE);
                }
                qemu_system_shutdown_request_with_code(cause, code);
                break;
            }
            case QUIESCE:
            case DRAIN: {
                RouterBarrier *barrier = type == QUIESCE ? &quiesce : &drain;
                MachineState *ms = MACHINE(qdev_get_machine());
                uint32_t version = qemu_get_be32(req_file);
                uint32_t sender = qemu_get_be32(req_file);
                uint32_t target = qemu_get_be32(req_file);
                uint64_t nonce = qemu_get_be64(req_file);

                if (qemu_file_get_error(req_file) || version != ROUTER_PROTOCOL_VERSION ||
                    sender >= ms->qemu_nums || sender == router_index() ||
                    target != router_index() || cpu_index != CPU_INDEX_ANY || !nonce) {
                    error_report("SSI invalid drain marker");
                    exit(EXIT_FAILURE);
                }
                qemu_mutex_lock(&drain_mutex);
                if (barrier->seen & (UINT64_C(1) << sender)) {
                    error_report("SSI duplicate drain marker");
                    exit(EXIT_FAILURE);
                }
                if (type == DRAIN && !(quiesce.received & (UINT64_C(1) << sender))) {
                    error_report("SSI device drain preceded CPU quiescence");
                    _exit(EXIT_FAILURE);
                }
                if (type == QUIESCE && sender == 0) {
                    close_generation = nonce;
                }
                barrier->seen |= UINT64_C(1) << sender;
                int64_t deadline = qemu_clock_get_ms(QEMU_CLOCK_REALTIME) + ROUTER_DRAIN_TIMEOUT_MS;
                /* 本流的先前设备操作已完成；本地尚未排空时不能提前确认。 */
                while (!qatomic_read(&barrier->started)) {
                    int64_t left = deadline - qemu_clock_get_ms(QEMU_CLOCK_REALTIME);
                    if (left <= 0) {
                        error_report("SSI local quiescence deadline expired");
                        exit(EXIT_FAILURE);
                    }
                    qemu_cond_timedwait(&drain_cond, &drain_mutex, left);
                }
                /* 网络写入不能持屏障锁，否则截止时间线程无法报告发送阻塞。 */
                qemu_mutex_unlock(&drain_mutex);
                qemu_put_be32(rsp_file, ROUTER_DRAIN_ACK);
                qemu_put_be32(rsp_file, ROUTER_PROTOCOL_VERSION);
                qemu_put_be32(rsp_file, target);
                qemu_put_be32(rsp_file, sender);
                qemu_put_be64(rsp_file, nonce);
                qemu_fflush(rsp_file);
                if (qemu_file_get_error(rsp_file)) {
                    error_report("SSI drain acknowledgement send failed");
                    exit(EXIT_FAILURE);
                }
                qemu_mutex_lock(&drain_mutex);
                barrier->received |= UINT64_C(1) << sender;
                drained = type == DRAIN;
                fprintf(stderr, "SSI_%s_ACK_SENT node=%u peer=%u nonce=%" PRIu64 "\n",
                        barrier->name, target, sender, nonce);
                qemu_cond_broadcast(&drain_cond);
                qemu_mutex_unlock(&drain_mutex);
                break;
            }
            case RESET:
                /* 复位保留连接，继续接收关闭通知、排空标记和对端断连。 */
                qemu_system_reset_request(SHUTDOWN_CAUSE_GUEST_RESET);
                break;
            case EXIT:
                exit(0);
                break;

            default:
                printf("unknown type[%u]\n", type);
                exit(1);
        }
    }
    if (argp->channel) {
        qio_channel_close(argp->channel, &err);
    }
    return NULL;
}

#ifdef ROUTER_CONNECTION_RDMA
/* TODO: Do real router address resolve */
static int get_rdma_router_address(int target, int role, struct router_address *addr)
{
    int host;
    int port;
    int qemu_index;
    MachineState *ms = MACHINE(qdev_get_machine());

    if (addr == NULL) {
        return -EINVAL;
    }

    if (target < 0 || target > ROUTER_MAX_INDEX) {
        return -EINVAL;
    }

    qemu_index = ms->local_cpu_start_index / ms->local_cpus;

    switch (role) {
        case RDMA_LISTEN:
            host = qemu_index;
            port = ms->qemu_nums * qemu_index * 2 + target * 2;
            break;
        case RDMA_CONNECT_REVERSE:
            host = qemu_index;
            port = ms->qemu_nums * qemu_index * 2 + target * 2 + 1;
            break;
        case RDMA_CONNECT:
            host = target;
            port = ms->qemu_nums * target * 2 + qemu_index * 2;
            break;
        case RDMA_LISTEN_REVERSE:
            host = target;
            port = ms->qemu_nums * target * 2 + qemu_index * 2 + 1;
            break;
        default:
            printf("get_rdma_router_address failed. role %d is illegal\n", role);
            return -EINVAL;
    }

    sprintf(addr->host, "%s", router_hosts[host]);
    sprintf(addr->port, "%d", ROUTER_DEFAULT_PORT + port);
    addr->target = target;
    return 0;
}

static void qemu_io_router_thread_run_rdma(void)
{
    int ret;
    struct router_address addr;
    int i = 0;
    int done = 0;

    MachineState *ms = MACHINE(qdev_get_machine());

    // we build 2x connection since the connection is simplex
    for (i = 0; i < ms->qemu_nums; i++) {
        if (i == ms->local_cpu_start_index / ms->local_cpus) {
            continue;
        }
        ret = get_rdma_router_address(i, RDMA_LISTEN, &addr);
        if (ret) {
            printf("get_router_address failed, ret: %d\n", ret);
            return;
        }
        printf("QEMU %d wait for RDMA connection on %s:%s\n", i, addr.host, addr.port);

        listen_rsp_files[i] = qemu_rdma_build_incoming_file(&addr);
        ret = get_rdma_router_address(i, RDMA_CONNECT_REVERSE, &addr);
        if (ret) {
            printf("get_router_address failed, ret: %d\n", ret);
            return;
        }
        rsp_files[i] = qemu_rdma_build_incoming_file(&addr);
        printf("QEMU %d wait for RDMA connection on %s:%s\n", i, addr.host, addr.port);
    }

    while (done < ms->qemu_nums - 1) {
        for (i = 0; i < ms->qemu_nums; i++) {
            if (listen_req_files[i]) {
                struct io_router_loop_arg *arg = (struct io_router_loop_arg *)g_malloc0(sizeof(struct io_router_loop_arg));
                memset(arg, 0, sizeof(struct io_router_loop_arg));
                arg->req_file = listen_rsp_files[i];
                arg->rsp_file = listen_req_files[i];

                QemuThread *thread = g_malloc0(sizeof(QemuThread));
                qemu_thread_create(thread, "io-router-connection", io_router_loop,
                           arg, QEMU_THREAD_JOINABLE);
                listen_req_files[i] = NULL;
                done++;
            }
        }
    }
}

static void connect_io_router_rdma(void)
{
    struct router_address addr;
    int ret;
    int i = 0;
    int done = 0;
    MachineState *ms = MACHINE(qdev_get_machine());
    int local_index = ms->local_cpu_start_index / ms->local_cpus;

    // we build 2x connection since the connection is simplex
    for (i = 0; i < ms->qemu_nums; i ++) {
        if (i == local_index) {
            continue;
        }
        ret = get_rdma_router_address(i, RDMA_CONNECT, &addr);
        if (ret) {
            printf("get_router_address failed, ret: %d\n", ret);
            return;
        }
        req_files[i] = qemu_rdma_build_outcoming_file(&addr);
        printf("QEMU %d connect to %d %s:%s success\n", local_index, i, addr.host, addr.port);
        printf("req_files[%d] connect to %s:%s success\n", i, addr.host, addr.port);

        ret = get_rdma_router_address(i, RDMA_LISTEN_REVERSE, &addr);
        if (ret) {
            printf("get_router_address failed, ret: %d\n", ret);
            return;
        }
        listen_req_files[i] = qemu_rdma_build_outcoming_file(&addr);
        printf("QEMU %d connect to QEMU %d %s:%s success\n", local_index, i, addr.host, addr.port);
    }

    bool *done_list = (bool *)g_malloc0(ms->qemu_nums * sizeof(bool));

    while (done < ms->qemu_nums - 1) {
        for (i = 0; i < ms->qemu_nums; i++) {
            if (rsp_files[i] && !done_list[i]) {
                done_list[i] = true;
                done++;
                printf("connect io router %d done\n", i);
            }
        }
    }
    free(done_list);
}

