static gboolean io_router_accept_connection(QIOChannel *ioc,
                                                 GIOCondition condition,
                                                 gpointer user_data)
{
    QIOChannelSocket *sioc;
    QIOChannel *channel;
    Error *err = NULL;

    sioc = qio_channel_socket_accept(QIO_CHANNEL_SOCKET(ioc),
                                     &err);
    if (!sioc) {
        error_report("could not accept io router connection (%s)",
                     error_get_pretty(err));
        exit(1);
    }


    channel = QIO_CHANNEL(sioc);
    qio_channel_set_name(channel, "io-router-connection-channel");

    QemuThread *thread = g_malloc0(sizeof(QemuThread));
    struct io_router_loop_arg *arg = (struct io_router_loop_arg *)g_malloc0(sizeof(struct io_router_loop_arg));
    memset(arg, 0, sizeof(struct io_router_loop_arg));
    arg->req_file = qemu_file_new_input(channel);
    arg->rsp_file = qemu_file_get_return_path(arg->req_file);
    arg->channel = channel;

    qemu_thread_create(thread, "io-router-connection", io_router_loop,
               arg, QEMU_THREAD_JOINABLE);

    return true;
}

static void connect_io_router_single(int index)
{
    QIOChannel *channel;
    SocketAddress *connect_addr;
    Error *err = NULL;

    connect_addr = g_new0(SocketAddress, 1);

#ifdef ROUTER_CONNECTION_UNIX_SOCKET
    char sockpath[30];
    sprintf(sockpath, "%s-%d", ROUTER_SOCKET_PREFIX, index);

    connect_addr->type = SOCKET_ADDRESS_KIND_UNIX;
    connect_addr->u.q_unix.data = g_new0(UnixSocketAddress, 1);
    connect_addr->u.q_unix.data->path = g_strdup(sockpath);
    printf("connect socket_path: %s\n", sockpath);
#endif

#ifdef ROUTER_CONNECTION_TCP
    int ret;
    struct router_address addr;
    memset(&addr, 0, sizeof(addr));

    ret = get_router_address(index, &addr);
    if (ret) {
        printf("get_router_address failed, ret: %d\n", ret);
        return;
    }
    connect_addr->type = SOCKET_ADDRESS_TYPE_INET;
    connect_addr->u.inet = (InetSocketAddress) {
        .host = g_strdup(addr.host),
        .port = g_strdup(addr.port), /* NULL == Auto-select */
        .has_ipv4 = true,
        .ipv4 =true,
    };
    printf("connecting %s:%s\n", addr.host, addr.port);
#endif

    channel = QIO_CHANNEL(qio_channel_socket_new());
    qio_channel_set_name(QIO_CHANNEL(channel), "io-send");

    while (true) {
        if (qio_channel_socket_connect_sync(QIO_CHANNEL_SOCKET(channel),
                                            connect_addr,
                                            &err) == 0) {
            break;
        }
        error_free(err);
        err = NULL;
        usleep(100000);
    }

    qio_channel_set_delay(channel, false);
    req_files[index] = qemu_file_new_output(channel);
    rsp_files[index] = qemu_file_get_return_path(req_files[index]);
    router_write_hello(req_files[index], ROUTER_HELLO, index);
    unsigned int peer = router_read_hello(rsp_files[index], ROUTER_HELLO_ACK);
    if (peer != index) {
        router_startup_fail("reply came from the wrong peer");
    }
    fprintf(stderr, "SSI_ROUTER_HELLO_ACK node=%u peer=%u version=%u\n",
            router_index(), peer, ROUTER_PROTOCOL_VERSION);
    qapi_free_SocketAddress(connect_addr);
    printf("connecting io router done\n");
}
#endif /* ROUTER_CONNECTION_RDMA */

static void *qemu_io_router_thread_run(void *arg)
{
    IORouter *router = arg;
    router->thread_id = qemu_get_thread_id();

#ifdef ROUTER_CONNECTION_RDMA
    qemu_io_router_thread_run_rdma();
#else
    int ret;
    SocketAddress *listen_addr;
    QIOChannelSocket *lioc;
    Error *local_err = NULL;
    listen_addr = g_new0(SocketAddress, 1);
    MachineState *ms = MACHINE(qdev_get_machine());
    int index = ms->local_cpu_start_index / ms->local_cpus;

#ifdef ROUTER_CONNECTION_UNIX_SOCKET
    char sockpath[30];
    sprintf(sockpath, "%s-%d", ROUTER_SOCKET_PREFIX, index);

    listen_addr->type = SOCKET_ADDRESS_KIND_UNIX;
    listen_addr->u.q_unix.data = g_new0(UnixSocketAddress, 1);
    listen_addr->u.q_unix.data->path = g_strdup(sockpath);

    printf("QEMU %d listen on Unix socket %s\n", index, sockpath);
#endif

#ifdef ROUTER_CONNECTION_TCP
    struct router_address addr;
    memset(&addr, 0, sizeof(addr));

    ret = get_router_address(index, &addr);
    if (ret) {
        printf("get_router_address failed, ret: %d\n", ret);
        return NULL;
    }
    listen_addr->type = SOCKET_ADDRESS_TYPE_INET;
    listen_addr->u.inet = (InetSocketAddress) {
        .host = g_strdup(addr.host),
        .port = g_strdup(addr.port), /* NULL == Auto-select */
        .has_ipv4 = true,
        .ipv4 =true,
    };
    printf("QEMU %d listen on TCP socket %s:%s\n", index, addr.host, addr.port);
#endif

    lioc = qio_channel_socket_new();
    qio_channel_set_name(QIO_CHANNEL(lioc), "io-router-listener-channel");

    if (qio_channel_socket_listen_sync(lioc, listen_addr, 1, &local_err) < 0) {
        printf("io-router listen error, exit...");
        object_unref(OBJECT(lioc));
        qapi_free_SocketAddress(listen_addr);
        exit(1);
    }

    qapi_free_SocketAddress(listen_addr);
    /* 启动阶段主循环尚未接收事件，独立监听线程必须能处理双向握手。 */
    for (unsigned int peer = 0; peer < ms->qemu_nums - 1; peer++) {
        qio_channel_wait(QIO_CHANNEL(lioc), G_IO_IN);
        io_router_accept_connection(QIO_CHANNEL(lioc), G_IO_IN, NULL);
    }
    /* 本轮所需连接已接收，关闭监听器，禁止关闭设备时再创建接收线程。 */
    object_unref(OBJECT(lioc));
#endif
    return NULL;
}

static void connect_io_router(void)
{
    printf("connect_io_router...\n");

#ifdef ROUTER_CONNECTION_RDMA
    connect_io_router_rdma();
#else
    MachineState *ms = MACHINE(qdev_get_machine());
    int index = ms->local_cpu_start_index / ms->local_cpus;

    int i;
    for (i = 0; i < ms->qemu_nums; i++) {
        if (i != index) {
            connect_io_router_single(i);
        }
    }
#endif
    printf("connect_io_router done\n");

}


/* 在 vCPU 停止且块层排空之后执行；路由处理器在此期间仍负责完成先前请求。 */
static void router_barrier(RouterBarrier *barrier, unsigned int type)
{
    MachineState *ms = MACHINE(qdev_get_machine());
    QemuThread watchdog;
    CPUState *cpu;
    unsigned int index = router_index();
    uint64_t expected;
    unsigned int stopped = 0;

    if (ms->local_cpus == ms->smp.cpus) {
        return;
    }
    CPU_FOREACH(cpu) {
        if (!cpu->stopped) {
            error_report("SSI drain reached before vCPU %d stopped", cpu->cpu_index);
            exit(EXIT_FAILURE);
        }
        stopped++;
    }
    expected = (UINT64_MAX >> (64 - ms->qemu_nums)) & ~(UINT64_C(1) << index);
    /* 序号只关联同一 TCP 会话内的确认，不提供协议认证或跨连接重放保护。 */
    barrier->nonce = qemu_clock_get_ns(QEMU_CLOCK_REALTIME) | UINT64_C(1);
    qemu_thread_create(&watchdog, "ssi-drain-deadline", router_drain_watchdog,
                       barrier, QEMU_THREAD_JOINABLE);
    qemu_mutex_lock(&io_forwarding_mutex);
    qemu_mutex_lock(&drain_mutex);
    if (barrier->started) {
        error_report("SSI duplicate local barrier");
        _exit(EXIT_FAILURE);
    }
    if (type == QUIESCE && index == 0) {
        close_generation = barrier->nonce;
    }
    qatomic_set(&barrier->started, true);
    fprintf(stderr, "SSI_%s_LOCAL node=%u stopped=%u nonce=%" PRIu64 "\n",
            barrier->name, index, stopped, barrier->nonce);
    qemu_cond_broadcast(&drain_cond);
    qemu_mutex_unlock(&drain_mutex);
    /* 先向所有对端发送标记，再读取确认，避免不同遍历顺序导致互等。 */
    for (unsigned int peer = 0; peer < ms->qemu_nums; peer++) {
        if (peer == index) {
            continue;
        }
        if (!req_files[peer] || !rsp_files[peer]) {
            error_report("SSI missing drain connection");
            exit(EXIT_FAILURE);
        }
        qemu_put_be16(req_files[peer], type);
        qemu_put_sbe32(req_files[peer], CPU_INDEX_ANY);
        qemu_put_be32(req_files[peer], ROUTER_PROTOCOL_VERSION);
        qemu_put_be32(req_files[peer], index);
        qemu_put_be32(req_files[peer], peer);
        qemu_put_be64(req_files[peer], barrier->nonce);
        qemu_fflush(req_files[peer]);
        if (qemu_file_get_error(req_files[peer])) {
            error_report("SSI drain marker send failed");
            exit(EXIT_FAILURE);
        }
    }
    for (unsigned int peer = 0; peer < ms->qemu_nums; peer++) {
        if (peer == index) {
            continue;
        }
        uint32_t magic = qemu_get_be32(rsp_files[peer]);
        uint32_t version = qemu_get_be32(rsp_files[peer]);
        uint32_t sender = qemu_get_be32(rsp_files[peer]);
        uint32_t target = qemu_get_be32(rsp_files[peer]);
        uint64_t nonce = qemu_get_be64(rsp_files[peer]);
        if (qemu_file_get_error(rsp_files[peer]) || magic != ROUTER_DRAIN_ACK ||
            version != ROUTER_PROTOCOL_VERSION || sender != peer ||
            target != index || nonce != barrier->nonce) {
            error_report("SSI missing or invalid drain acknowledgement");
            exit(EXIT_FAILURE);
        }
        fprintf(stderr, "SSI_%s_ACK_RECEIVED node=%u peer=%u nonce=%" PRIu64 "\n",
                barrier->name, index, peer, nonce);
    }
    qemu_mutex_unlock(&io_forwarding_mutex);
    qemu_mutex_lock(&drain_mutex);
    while (barrier->received != expected) {
        qemu_cond_wait(&drain_cond, &drain_mutex);
    }
    barrier->finished = true;
    qemu_cond_broadcast(&drain_cond);
    qemu_mutex_unlock(&drain_mutex);
    qemu_thread_join(&watchdog);
    fprintf(stderr, "SSI_%s_COMPLETE node=%u peers=%u\n", barrier->name, index, ms->qemu_nums - 1);
}

/* 双端停止所有 vCPU 并处理此前的路由报文，设备清理仍允许产生中断。 */
uint64_t quiesce_io_router(void)
{
    router_barrier(&quiesce, QUIESCE);
    return close_generation;
}

/* 所有设备清理完成后才禁止新的转发，随后进入内核关闭协议。 */
void drain_io_router(void)
{
    router_barrier(&drain, DRAIN);
}

void disconnect_io_router(void)
{
    MachineState *ms = MACHINE(qdev_get_machine());
    if (ms->local_cpus == ms->smp.cpus) {
        return;
    }

    QEMUFile *io_connect_file;
    QEMUFile *io_connect_return_file;

    int i;
    for (i = 0; i < ms->qemu_nums; i++) {
        io_connect_file = req_files[i];
        io_connect_return_file = rsp_files[i];

        if (io_connect_file && io_connect_return_file) {
            qemu_file_shutdown(io_connect_file);
            qemu_file_shutdown(io_connect_return_file);
        }
        g_free(router_hosts[i]);
    }
    g_free(req_files);
    g_free(rsp_files);
    g_free(listen_req_files);
    g_free(listen_rsp_files);
    g_free(router_hosts);
}

void start_io_router(void)
{
    IORouter router;
    QemuThread watchdog;
    router.thread_id = -1;
    int size;

    MachineState *ms = MACHINE(qdev_get_machine());
    qemu_mutex_init(&io_forwarding_mutex);
    qemu_mutex_init(&ipi_mutex);
    qemu_mutex_init(&drain_mutex);
    qemu_cond_init(&drain_cond);
    qemu_mutex_init(&startup_mutex);
    qemu_cond_init(&startup_cond);
    if (ms->local_cpus == ms->smp.cpus) {
        return;
    }

    if (ms->qemu_nums < 2 || ms->qemu_nums > 64) {
        error_report("SSI drain supports 2 through 64 router nodes");
        exit(EXIT_FAILURE);
    }
    if (router_hosts_num != ms->qemu_nums) {
        error_report("invalid number of cluster iplist");
        exit(1);
    }

    size = ms->qemu_nums * sizeof(QEMUFile *);
    req_files = (QEMUFile **)g_malloc0(size);
    rsp_files = (QEMUFile **)g_malloc0(size);
    listen_req_files = (QEMUFile **)g_malloc0(size);
    listen_rsp_files = (QEMUFile **)g_malloc0(size);


    qemu_thread_create(&watchdog, "ssi-start-deadline", router_startup_watchdog,
                       NULL, QEMU_THREAD_JOINABLE);
    qemu_thread_create(&(router.thread), "io-router-listener", qemu_io_router_thread_run,
                       &router, QEMU_THREAD_JOINABLE);

    connect_io_router();
    uint64_t expected = (UINT64_MAX >> (64 - ms->qemu_nums)) &
                        ~(UINT64_C(1) << router_index());
    qemu_mutex_lock(&startup_mutex);
    while (startup_received != expected) {
        qemu_cond_wait(&startup_cond, &startup_mutex);
    }
    startup_complete = true;
    qemu_cond_broadcast(&startup_cond);
    qemu_mutex_unlock(&startup_mutex);
    qemu_thread_join(&watchdog);
    qemu_thread_join(&router.thread);
    fprintf(stderr, "SSI_ROUTER_READY node=%u peers=%u version=%u\n",
            router_index(), ms->qemu_nums - 1, ROUTER_PROTOCOL_VERSION);
}

/*
 * Currently we put all devices on QEMU 0, so we only need to forward PIOs on
 * APs to BSP. (except for PIOs to PCI configuration space)
 * TODO: support the conceptial "Virtual PCI-e Bus". @jinzhang
 */
void pio_forwarding(uint16_t port, MemTxAttrs attrs, void *data, int direction,
                          int size, uint32_t count, bool broadcast)
{
    router_forward_lock();

    QEMUFile *io_connect_file;
    QEMUFile *io_connect_return_file;

    MachineState *ms = MACHINE(qdev_get_machine());

    if (broadcast) {
        int i;
        for (i = 0; i < ms->qemu_nums; i++) {
            io_connect_file = req_files[i];
            io_connect_return_file = rsp_files[i];

            if (io_connect_file && io_connect_return_file) {
                qemu_put_be16(io_connect_file, PIO);
                /*
                 * indicate which cpu we are currently operating on, especially
                 * for apic_mem_readl / apic_mem_writel => cpu_get_current_apic
                 */
                qemu_put_sbe32(io_connect_file, CPU_INDEX_ANY);
                qemu_put_be16(io_connect_file, port);
                qemu_put_buffer(io_connect_file, (uint8_t *)&attrs, sizeof(attrs));
                qemu_put_sbe32(io_connect_file, direction);
                qemu_put_sbe32(io_connect_file, size);
                qemu_put_be32(io_connect_file, count);
                qemu_put_buffer(io_connect_file, data, count * size);

                qemu_fflush(io_connect_file);

                if (direction == KVM_EXIT_IO_IN) {
                    qemu_get_buffer(io_connect_return_file, data, count * size);
                }

            }
        }
    } else {
        /* @unicast: AP -> BSP (i.e. QEMU[0]) */
        io_connect_file = req_files[0];
        io_connect_return_file = rsp_files[0];

        qemu_put_be16(io_connect_file, PIO);
        /*
         * indicate which cpu we are currently operating on, especially for
         * apic_mem_readl / apic_mem_writel => cpu_get_current_apic
         */
        qemu_put_sbe32(io_connect_file, current_cpu->cpu_index);
        qemu_put_be16(io_connect_file, port);
        qemu_put_buffer(io_connect_file, (uint8_t *)&attrs, sizeof(attrs));
        qemu_put_sbe32(io_connect_file, direction);
        qemu_put_sbe32(io_connect_file, size);
        qemu_put_be32(io_connect_file, count);
        qemu_put_buffer(io_connect_file, data, count * size);

        qemu_fflush(io_connect_file);

        if (direction == KVM_EXIT_IO_IN) {
            qemu_get_buffer(io_connect_return_file, data, count * size);
        }
    }

    qemu_mutex_unlock(&io_forwarding_mutex);
}

/*
 * @unicast: AP -> BSP (i.e. QEMU[0])
 *
 * Currently we put all devices on QEMU 0, so we only need to forward MMIOs on APs to BSP.
 * TODO: support the conceptial "Virtual PCI-e Bus". @jinzhang
 */
void mmio_forwarding(hwaddr addr, MemTxAttrs attrs, uint8_t *data, int len, bool is_write)
{
    router_forward_lock();

    QEMUFile *io_connect_file = req_files[0];
    QEMUFile *io_connect_return_file = rsp_files[0];

    qemu_put_be16(io_connect_file, MMIO);
    /*
     * indicate which cpu we are currently operating on, especially for
     * apic_mem_readl / apic_mem_writel => cpu_get_current_apic
     */
    qemu_put_sbe32(io_connect_file, current_cpu->cpu_index);
    qemu_put_be64(io_connect_file, addr);
    qemu_put_buffer(io_connect_file, (uint8_t *)&attrs, sizeof(attrs));
    qemu_put_sbe32(io_connect_file, len);
    if (is_write) {
        qemu_put_sbe32(io_connect_file, 1);
    }
    else {
        qemu_put_sbe32(io_connect_file, 0);
    }
    qemu_put_buffer(io_connect_file, data, len);

    qemu_fflush(io_connect_file);
    if (qemu_file_get_error(io_connect_file)) {
        error_report("SSI MMIO request failed: %s",
                     strerror(-qemu_file_get_error(io_connect_file)));
        exit(1);
    }

    bool complete;
    if (!is_write) {
        complete = qemu_get_buffer(io_connect_return_file, data, len) == len;
    } else {
        /* 持有同一连接锁直到收到实际执行后的确认，避免响应被下一请求消费。 */
        complete = qemu_get_be32(io_connect_return_file) == MMIO_WRITE_COMPLETE;
    }
    if (!complete || qemu_file_get_error(io_connect_return_file)) {
        error_report("SSI MMIO missing or invalid completion");
        exit(1);
    }

    qemu_mutex_unlock(&io_forwarding_mutex);
}

/* @broadcast */
void lapic_forwarding(int cpu_index, hwaddr addr, uint32_t val)
{
    router_forward_lock();
    QEMUFile *io_connect_file;

    MachineState *ms = MACHINE(qdev_get_machine());

    int i;
    for (i = 0; i < ms->qemu_nums; i++) {
        io_connect_file = req_files[i];
        if (io_connect_file) {
            qemu_put_be16(io_connect_file, LAPIC);
            /*
             * indicate which cpu we are currently operating on, especially for
             * apic_mem_readl / apic_mem_writel => cpu_get_current_apic
             */
            qemu_put_sbe32(io_connect_file, cpu_index);
            qemu_put_be64(io_connect_file, addr);
            qemu_put_be32(io_connect_file, val);
            qemu_fflush(io_connect_file);
        }
    }

    qemu_mutex_unlock(&io_forwarding_mutex);
}

/* @unicast: current CPU -> dest CPU (CPU No. cpu_index) */
void special_interrupt_forwarding(int cpu_index, int mask)
{
    router_forward_lock();
    MachineState *ms = MACHINE(qdev_get_machine());
    QEMUFile *io_connect_file = req_files[cpu_index / ms->local_cpus];

    qemu_put_be16(io_connect_file, SPECIAL_INT);
    /* Indicate which CPU we want to forward this interrupt to */
    qemu_put_sbe32(io_connect_file, cpu_index);
    qemu_put_sbe32(io_connect_file, mask);
    qemu_fflush(io_connect_file);

    qemu_mutex_unlock(&io_forwarding_mutex);
}

/* @unicast: current CPU -> dest CPU (CPU No. cpu_index) */
void startup_forwarding(int cpu_index, uint32_t val, uint32_t val2, uint32_t dest_id)
{
    router_forward_lock();
    MachineState *ms = MACHINE(qdev_get_machine());
    QEMUFile *io_connect_file;

      for (int i = 0; i < ms->qemu_nums; i++) {
        if (i == (cpu_index / ms->local_cpus)) {
            continue;
        }
        io_connect_file = req_files[i];
        if (io_connect_file) {
            qemu_put_be16(io_connect_file, SIPI);
            /* Indicate which CPU we want to forward this interrupt to */
            qemu_put_sbe32(io_connect_file, cpu_index);
            qemu_put_be32(io_connect_file, val);
            qemu_put_be32(io_connect_file, val2);
            qemu_put_be32(io_connect_file, dest_id);
