void ioapic_irq_forwarding(int irq, int level)
{
    router_forward_lock();
    QEMUFile *io_connect_file = req_files[0];
    MachineState *ms = MACHINE(qdev_get_machine());
    for (int i = 1; i < ms->qemu_nums; i++) {
        io_connect_file = req_files[i];
        if (io_connect_file) {
           qemu_put_be16(io_connect_file, IOAPIC_INI);
           qemu_put_sbe32(io_connect_file, CPU_INDEX_ANY);
           qemu_put_sbe32(io_connect_file, irq);
           qemu_put_sbe32(io_connect_file, level);
           qemu_fflush(io_connect_file);
        }
    }
    qemu_mutex_unlock(&io_forwarding_mutex);
}

void ioapic_router_forwarding(struct kvm_irq_routing *routing) {
    router_forward_lock();
    QEMUFile *io_connect_file = req_files[1];

    qemu_put_be16(io_connect_file, INI_ROUTER);
    qemu_put_sbe32(io_connect_file, CPU_INDEX_ANY);
    qemu_put_be32(io_connect_file, routing->nr);     
    qemu_put_be32(io_connect_file, routing->flags);  

    for (int i = 0; i < routing->nr; i++) {
        struct kvm_irq_routing_entry *entry = &(routing->entries[i]);

        qemu_put_be32(io_connect_file, entry->gsi);
        qemu_put_be32(io_connect_file, entry->type);
        qemu_put_be32(io_connect_file, entry->flags);
        qemu_put_be32(io_connect_file, entry->pad); 

        switch (entry->type) {
            case KVM_IRQ_ROUTING_IRQCHIP: {
                struct kvm_irq_routing_irqchip *irq = &(entry->u.irqchip);
                qemu_put_be32(io_connect_file, irq->irqchip); 
                qemu_put_be32(io_connect_file, irq->pin);
                break;
            }
            case KVM_IRQ_ROUTING_MSI: {
                struct kvm_irq_routing_msi *msi = &(entry->u.msi);
                qemu_put_be32(io_connect_file, msi->address_lo);
                qemu_put_be32(io_connect_file, msi->address_hi);
                qemu_put_be32(io_connect_file, msi->data);
                qemu_put_be32(io_connect_file, msi->pad);
                break;
            }
            default:
                fprintf(stderr, "Unsupported routing type: %d\n", entry->type);
                break;
        }
    }

    qemu_fflush(io_connect_file); 
    io_connect_file = rsp_files[1];
    while(qemu_get_be32(io_connect_file) != 99) {
    }
    qemu_mutex_unlock(&io_forwarding_mutex);
}

/* @unicast: AP -> BSP (i.e. QEMU[0]) */
void eoi_forwarding(int isrv)
{
    router_forward_lock();
    QEMUFile *io_connect_file = req_files[0];

    qemu_put_be16(io_connect_file, IOAPIC);
    qemu_put_sbe32(io_connect_file, CPU_INDEX_ANY);
    qemu_put_sbe32(io_connect_file, isrv);
    qemu_fflush(io_connect_file);

    qemu_mutex_unlock(&io_forwarding_mutex);
}

/* @broadcast */
void shutdown_forwarding(ShutdownCause reason, int exit_code)
{
    router_forward_lock();
    QEMUFile *io_connect_file;

    MachineState *ms = MACHINE(qdev_get_machine());

    int i;
    for (i = 0; i < ms->qemu_nums; i++) {
        io_connect_file = req_files[i];
        if (io_connect_file) {
            qemu_put_be16(io_connect_file, SHUTDOWN);
            qemu_put_sbe32(io_connect_file, CPU_INDEX_ANY);
            qemu_put_be32(io_connect_file, ROUTER_PROTOCOL_VERSION);
            qemu_put_be32(io_connect_file, reason);
            qemu_put_sbe32(io_connect_file, exit_code);
            qemu_fflush(io_connect_file);
            if (qemu_file_get_error(io_connect_file)) {
                error_report("SSI shutdown notification failed");
                exit(EXIT_FAILURE);
            }
        }
    }

    qemu_mutex_unlock(&io_forwarding_mutex);
}

/* @broadcast */
void reset_forwarding(void)
{
    router_forward_lock();
    QEMUFile *io_connect_file;

    MachineState *ms = MACHINE(qdev_get_machine());

    int i;
    for (i = 0; i < ms->qemu_nums; i++) {
        io_connect_file = req_files[i];
        if (io_connect_file) {
            qemu_put_be16(io_connect_file, RESET);
            qemu_put_sbe32(io_connect_file, CPU_INDEX_ANY);
            qemu_fflush(io_connect_file);
        }
    }

    qemu_mutex_unlock(&io_forwarding_mutex);
}

/* @broadcast */
void exit_forwarding(void)
{
    router_forward_lock();
    QEMUFile *io_connect_file;
    MachineState *ms = MACHINE(qdev_get_machine());

    int i;
    for (i = 0; i < ms->qemu_nums; i++) {
        io_connect_file = req_files[i];
        if (io_connect_file) {
            qemu_put_be16(io_connect_file, EXIT);
            qemu_put_sbe32(io_connect_file, CPU_INDEX_ANY);
            qemu_fflush(io_connect_file);
        }
    }

    qemu_mutex_unlock(&io_forwarding_mutex);
}

int kvmclock_fetching(uint64_t epoch, KVMClockSample *sample)
{
    int ret;
    uint32_t version;

    router_forward_lock();

    QEMUFile *io_connect_file = req_files[0];
    QEMUFile *io_connect_return_file = rsp_files[0];

    qemu_put_be16(io_connect_file, KVMCLOCK);
    qemu_put_sbe32(io_connect_file, CPU_INDEX_ANY);
    qemu_put_be64(io_connect_file, epoch);
    qemu_fflush(io_connect_file);

    version = qemu_get_be32(io_connect_return_file);
    ret = qemu_get_sbe32(io_connect_return_file);
    sample->epoch = qemu_get_be64(io_connect_return_file);
    sample->clock = qemu_get_be64(io_connect_return_file);
    sample->host_tsc = qemu_get_be64(io_connect_return_file);
    sample->offset = qemu_get_be64(io_connect_return_file);
    sample->flags = qemu_get_be32(io_connect_return_file);
    sample->khz = qemu_get_be32(io_connect_return_file);
    if (qemu_file_get_error(io_connect_file)) {
        ret = qemu_file_get_error(io_connect_file);
    } else if (qemu_file_get_error(io_connect_return_file)) {
        ret = qemu_file_get_error(io_connect_return_file);
    } else if (version != ROUTER_PROTOCOL_VERSION || (!ret && sample->epoch != epoch)) {
        ret = -EPROTO;
    }
    qemu_mutex_unlock(&io_forwarding_mutex);
    return ret;
}

/* 调用方的独立截止时间线程覆盖互斥锁等待、发送和读取。 */
int kvmclock_barrier(uint64_t epoch, uint32_t phase,
                     uint64_t clock_floor, uint64_t tsc_floor)
{
    unsigned int index = router_index();
    unsigned int peer = index ^ 1;
    QEMUFile *request = req_files[peer];
    QEMUFile *response = rsp_files[peer];
    int ret = 0;

    router_forward_lock();
    qemu_put_be16(request, CLOCK_BARRIER);
    qemu_put_sbe32(request, CPU_INDEX_ANY);
    qemu_put_be32(request, ROUTER_PROTOCOL_VERSION);
    qemu_put_be32(request, index);
    qemu_put_be32(request, peer);
    qemu_put_be64(request, epoch);
    qemu_put_be32(request, phase);
    qemu_put_be64(request, clock_floor);
    qemu_put_be64(request, tsc_floor);
    qemu_fflush(request);
    uint32_t version = qemu_get_be32(response);
    uint32_t sender = qemu_get_be32(response);
    uint32_t target = qemu_get_be32(response);
    uint64_t observed_epoch = qemu_get_be64(response);
    uint32_t observed_phase = qemu_get_be32(response);
    if (qemu_file_get_error(request) || qemu_file_get_error(response)) {
        ret = -EIO;
    } else if (version != ROUTER_PROTOCOL_VERSION || sender != peer ||
               target != index || observed_epoch != epoch || observed_phase != phase) {
        ret = -EPROTO;
    }
    qemu_mutex_unlock(&io_forwarding_mutex);
    return ret;
}

